<?php
use App\Application\Partners\LicensingService;use App\Models\Partner;use App\Models\Party;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;
uses(RefreshDatabase::class);
test('verified licence activates partner and records decision evidence',function(){$actor=User::factory()->create();$party=Party::create(['type'=>'ORGANIZATION','display_name'=>'Licensed Broker','legal_identity'=>[],'status'=>'ACTIVE']);$partner=Partner::create(['party_id'=>$party->id,'type'=>'BROKER','status'=>'PENDING','compliance'=>[]]);$service=app(LicensingService::class);$licence=$service->submit($partner,['authority'=>'MINFI','licence_type'=>'BROKER','licence_number'=>'MINFI-B-001','issued_on'=>today(),'expires_on'=>today()->addYear()]);$service->decide($licence,'VERIFIED','MINFI register and supporting document verified',$actor);expect($licence->refresh()->status)->toBe('VERIFIED')->and($partner->refresh()->status)->toBe('ACTIVE')->and($partner->licence_number)->toBe('MINFI-B-001');$this->assertDatabaseHas('partner_status_history',['partner_id'=>$partner->id,'to_status'=>'ACTIVE']);});
